-- Phase B.7 - verified learning catalogue completion (4 of 5)
--
-- This migration ADDS 80 verified learning resources.
-- Every URL below was loaded and confirmed to return HTTP 200 with a page
-- title and body text that prove the topic; nothing is included on the
-- strength of a plausible-looking URL alone.
--
-- It is idempotent: re-applying it updates the same rows and never
-- duplicates them. It deletes nothing: no course, no mapping and no user
-- row is removed.

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  provider = EXCLUDED.provider,
  provider_url = EXCLUDED.provider_url,
  category = EXCLUDED.category,
  level = EXCLUDED.level,
  duration_hours = EXCLUDED.duration_hours,
  language = EXCLUDED.language,
  url = EXCLUDED.url,
  availability = EXCLUDED.availability,
  availability_note = EXCLUDED.availability_note,
  format = EXCLUDED.format,
  description = EXCLUDED.description,
  is_verified = EXCLUDED.is_verified,
  verified_at = EXCLUDED.verified_at,
  updated_at = now();

-- Skill mapping -----------------------------------------------------------
ON CONFLICT (course_id, skill_name) DO UPDATE SET importance = EXCLUDED.importance;

-- Role mapping ------------------------------------------------------------
ON CONFLICT (course_id, role_slug) DO UPDATE SET relevance_score = EXCLUDED.relevance_score;
